"""Article-specific ENTENDA content for CC-10, arts. 803-826."""
from __future__ import annotations


def row(says, means, example, warning, term, definition, *, terms=None):
    return {
        "target": None,
        "o_que_diz": says,
        "o_que_significa": means,
        "exemplo_pratico": example,
        "atencao": warning,
        "palavras_dificeis": terms or [{"termo": term, "explicacao": definition}],
    }


ROWS = {
    "803": row("Uma pessoa pode assumir gratuitamente o dever de pagar renda periódica a outra.", "Na constituição gratuita de renda, o beneficiário recebe prestações sucessivas sem entregar contraprestação ao rendeiro. O vínculo nasce do contrato e deve observar a forma exigida nos artigos seguintes.", "Uma tia constitui renda mensal gratuita em favor do sobrinho durante prazo determinado.", "Gratuidade não elimina requisitos de validade nem autoriza confundir o contrato com doação comum: seu objeto é uma sequência de prestações periódicas.", "Constituição de renda", "contrato pelo qual alguém assume pagamentos periódicos em favor de outra pessoa"),
    "804": row("A renda também pode ser onerosa: bens são transferidos ao rendeiro em troca das prestações destinadas ao credor ou a terceiro.", "Nesse modelo, o patrimônio entregue funciona como contraprestação pela obrigação periódica. O beneficiário da renda pode ser quem transferiu os bens ou pessoa indicada por ele.", "Proprietário transfere imóvel a uma sociedade, que assume pagamentos mensais em favor dele.", "A transferência dos bens e o pagamento da renda são partes do mesmo arranjo oneroso. Devem ser observadas as formalidades próprias do bem transferido.", "Rendeiro", "pessoa que recebe os bens e assume o dever de pagar a renda"),
    "805": row("Na constituição onerosa de renda, o credor pode exigir garantia real ou pessoal no momento da contratação.", "A garantia protege o recebimento das prestações futuras. Pode recair sobre um bem ou resultar do compromisso de terceiro, conforme o que as partes validamente ajustarem.", "Ao transferir imóvel em troca de renda vitalícia, o credor exige hipoteca para assegurar os pagamentos.", "A garantia não nasce automaticamente: deve ser exigida e constituída conforme suas regras específicas. Ela não amplia a renda além do contrato.", "Garantia fidejussória", "garantia pessoal em que terceiro responde pela obrigação do devedor"),
    "806": row("A renda pode durar por prazo determinado ou por toda a vida, inclusive superar a vida do devedor, mas não a do credor beneficiário.", "A duração pode estar ligada a uma data ou à vida humana. Se o rendeiro morrer, seus sucessores podem continuar obrigados; falecido o credor cuja vida limita o contrato, a renda não pode prosseguir por essa modalidade.", "Pessoa assume renda vitalícia e morre antes do beneficiário; a obrigação pode alcançar sua sucessão.", "É preciso identificar qual vida foi adotada como referência e quem é o credor, inclusive quando o beneficiário é terceiro.", "Renda vitalícia", "renda devida enquanto viver a pessoa cuja vida foi tomada como limite contratual"),
    "807": row("A constituição de renda deve ser formalizada por escritura pública.", "A forma pública é requisito legal do contrato, independentemente de a renda ser gratuita ou onerosa. Documento particular não substitui a escritura quando este artigo incide.", "Duas pessoas ajustam renda vitalícia e comparecem ao tabelionato para lavrar a escritura.", "Não se trata apenas de meio de prova. A ausência da forma legal pode comprometer a validade do negócio, além das formalidades próprias dos bens envolvidos.", "Escritura pública", "instrumento lavrado por tabelião com fé pública e requisitos legais"),
    "808": row("É inválida a renda destinada a pessoa já morta ou que morra, em até trinta dias do contrato, de doença que já possuía quando ele foi celebrado.", "A regra impede constituir renda cuja duração vitalícia já seja impossível ou esteja imediatamente frustrada pela enfermidade preexistente que causa a morte no período legal.", "Beneficiário doente na assinatura falece vinte dias depois pela mesma enfermidade; a constituição é nula.", "A nulidade na segunda hipótese exige morte dentro de trinta dias e nexo com a doença preexistente. Morte por causa diversa não se enquadra automaticamente.", "Moléstia preexistente", "doença já presente quando o contrato foi celebrado"),
    "809": row("Com a entrega, os bens transferidos em troca da renda passam a pertencer ao rendeiro.", "Na renda onerosa, a tradição coloca os bens móveis no patrimônio de quem assumiu as prestações. O credor deixa de ser dono, embora mantenha o direito aos pagamentos e às garantias constituídas.", "Credor entrega títulos ao rendeiro; a partir da tradição, este se torna titular e deve pagar a renda acordada.", "Domínio e crédito de renda são posições distintas. Para imóveis, a transferência também depende das regras registrais aplicáveis.", "Tradição", "entrega juridicamente relevante de um bem, normalmente necessária à transferência de móvel"),
    "810": row("Se o rendeiro não pagar, o credor pode cobrar parcelas vencidas e exigir garantia para as futuras, sob risco de rescisão do contrato.", "O inadimplemento permite tutela simultânea do atraso e da segurança das prestações seguintes. Se o devedor não regularizar nem garantir o futuro, o vínculo pode ser desfeito conforme o regime aplicável.", "Rendeiro deixa três mensalidades em aberto; o credor cobra os atrasados e pede garantia das próximas.", "A rescisão não apaga automaticamente parcelas vencidas ou prejuízos. Devem ser apurados inadimplemento, providências exigidas e efeitos sobre os bens transferidos.", "Prestação atrasada", "parcela periódica que venceu e não foi paga"),
    "811": row("Quando a renda não é paga antecipadamente, o direito do credor se forma diariamente ao longo de cada período.", "A aquisição proporcional dia a dia evita que todo o período dependa de o beneficiário estar vivo apenas na data final. O contrato pode prever pagamento adiantado, hipótese ressalvada pelo artigo.", "Renda mensal vencida ao fim do mês é adquirida pelo beneficiário gradualmente a cada dia.", "Aquisição diária não significa exigibilidade diária: a data de pagamento continua sendo a prevista. Pagamento antecipado recebe tratamento diferente.", "Aquisição pro rata", "formação proporcional de um direito conforme transcorre o tempo"),
    "812": row("Renda criada para várias pessoas é dividida igualmente se não houver quotas definidas; em regra, a parte de quem morre não acresce às dos sobreviventes.", "A igualdade e a ausência de direito de acrescer são regras supletivas. O instrumento pode estabelecer percentuais diferentes ou prever que a quota do falecido passe aos demais beneficiários.", "Três beneficiários sem quotas recebem um terço cada; morrendo um, sua parte não aumenta automaticamente as outras.", "A estipulação contratual pode alterar ambas as presunções. Também é necessário verificar a duração da renda e efeitos sucessórios cabíveis.", "Direito de acrescer", "aumento da parcela dos sobreviventes pela extinção da parte de outro beneficiário"),
    "813": row("O instituidor pode proteger renda gratuita contra execuções atuais e futuras; montepios e pensões alimentícias recebem essa proteção por força da lei.", "A cláusula de impenhorabilidade preserva a função assistencial da renda gratuita. Para as categorias mencionadas no parágrafo, a isenção independe de declaração especial do instituidor.", "Doador constitui renda gratuita e declara que ela não responderá pelas execuções do beneficiário.", "A proteção do artigo não deve ser estendida sem análise a renda onerosa nem usada para legitimar fraude. Regras processuais e especiais continuam aplicáveis.", "Montepio", "benefício periódico destinado à manutenção de dependentes ou associados"),
    "814": row("Dívida comum de jogo ou aposta não pode ser cobrada, e o pagamento voluntário não é repetível, salvo dolo do ganhador ou incapacidade protegida do perdedor. Há exceções legais.", "A obrigação é inexigível, mas o pagamento espontâneo normalmente permanece com quem recebeu. A regra alcança negócios que disfarçam a dívida, preserva terceiro de boa-fé e não atinge jogos autorizados nem prêmios regulares de competições.", "Adulto paga espontaneamente aposta privada e depois não consegue reaver a quantia apenas por arrependimento.", "Jogos legalmente permitidos e competições esportivas, intelectuais ou artísticas regulares ficam fora da regra geral. Dolo, menoridade e interdição mudam o resultado.", "Obrigação natural", "dever sem cobrança judicial, cujo pagamento espontâneo normalmente não pode ser recuperado"),
    "815": row("Quem empresta dinheiro no próprio momento do jogo ou da aposta não pode exigir reembolso.", "O financiador que fornece recursos diretamente para apostar assume a inexigibilidade legal. A regra desestimula o crédito imediatamente vinculado à prática do jogo.", "Pessoa entrega dinheiro ao jogador na mesa para que ele faça nova aposta e depois tenta cobrá-lo.", "É necessário demonstrar a ligação temporal e finalística do empréstimo com o jogo. Crédito independente, concedido para outra finalidade, não entra automaticamente nesta hipótese.", "Reembolso", "devolução ao credor do valor que ele adiantou ou emprestou"),
    "816": row("As restrições sobre jogo e empréstimo para apostar não alcançam certos contratos de mercado liquidados apenas pela diferença entre preço ajustado e cotação no vencimento.", "Operações diferenciais sobre títulos, mercadorias ou valores são reconhecidas como contratos econômicos, e não tratadas como simples aposta, desde que possuam a estrutura descrita.", "Partes ajustam operação sobre mercadoria e, no vencimento, liquidam somente a diferença entre preço contratado e cotação.", "A exceção depende da natureza do ativo e da forma de liquidação. Ela não valida negócios ilícitos nem dispensa regulação financeira ou mercantil aplicável.", "Liquidação por diferença", "pagamento apenas da variação entre o preço contratado e o preço de referência"),
    "817": row("O sorteio utilizado para resolver disputa ou repartir bem comum é tratado como método de partilha ou de transação.", "Nesse contexto, o acaso serve como técnica para distribuir bens ou encerrar controvérsia, sem transformar o acordo em dívida de jogo.", "Dois coproprietários sorteiam qual deles ficará com cada obra de valor equivalente na divisão do acervo.", "O sorteio precisa estar ligado a uma partilha ou composição legítima. Não basta chamar uma aposta de partilha para afastar as regras dos artigos anteriores.", "Transação", "acordo com concessões recíprocas destinado a prevenir ou encerrar controvérsia"),
    "818": row("Na fiança, o fiador promete ao credor cumprir a obrigação do devedor se este não a satisfizer.", "A garantia cria responsabilidade pessoal acessória. O devedor continua sendo o obrigado principal, enquanto o fiador responde nos limites assumidos quando ocorre o inadimplemento.", "Fiador garante aluguel e pode ser cobrado se o locatário deixar de pagar.", "Fiança não transfere a dívida principal nem presume solidariedade. Extensão, benefício de ordem e eventuais renúncias dependem do contrato e dos artigos seguintes.", "Fiador", "terceiro que oferece garantia pessoal pelo cumprimento da dívida de outra pessoa"),
    "819": row("A fiança exige documento escrito e deve ser interpretada restritivamente.", "A obrigação do fiador só alcança o que foi expressamente assumido. Não se ampliam por analogia o valor, o prazo, as dívidas ou as pessoas garantidas.", "Instrumento garante somente aluguéis; outras obrigações não entram sem previsão escrita compatível.", "Forma escrita não equivale a solidariedade nem elimina requisitos da dívida principal. Cláusulas ambíguas não devem aumentar a responsabilidade do garantidor.", "Interpretação restritiva", "leitura que mantém a garantia dentro dos limites expressamente declarados"),
    "820": row("A fiança pode ser constituída sem conhecimento do devedor e até contra sua vontade.", "O contrato se forma entre credor e fiador. A concordância do devedor principal não é requisito, porque a garantia beneficia o recebimento do crédito.", "Parente oferece fiança diretamente ao banco, embora o mutuário discorde da garantia.", "A dispensa de consentimento não autoriza alterar a dívida principal. Relações internas e eventual regresso do fiador seguem regras próprias.", "Consentimento", "manifestação de concordância necessária à formação de determinado negócio"),
    "821": row("Dívida futura pode ser afiançada, mas o fiador somente será cobrado quando a obrigação principal estiver determinada e quantificada.", "A garantia pode preceder o nascimento ou a apuração final da dívida. A exigibilidade contra o fiador aguarda certeza sobre a existência e liquidez do débito.", "Fiador garante futuras compras empresariais; a cobrança só ocorre após apuração das entregas e do valor devido.", "A previsão de dívida futura deve respeitar a forma escrita e os limites assumidos. Expectativa genérica não permite cobrança antes da definição do débito.", "Dívida líquida", "obrigação cujo valor está determinado ou pode ser apurado por cálculo objetivo"),
    "822": row("Se o instrumento não limitar a garantia, a fiança alcança acessórios da dívida e despesas judiciais posteriores à citação do fiador.", "A garantia ampla acompanha encargos vinculados à obrigação principal. Quanto aos gastos do processo, o marco indicado é a citação do próprio fiador.", "Fiador sem limitação expressa responde pelo principal, encargos abrangidos e despesas processuais após sua citação.", "A extensão legal não supera limites expressos válidos nem inclui obrigações estranhas à dívida garantida. A citação do devedor não substitui a do fiador para esse efeito.", "Acessórios da dívida", "encargos ligados ao principal, como juros e consequências previstas para o débito"),
    "823": row("A fiança pode garantir valor menor ou condições mais leves; se exceder ou agravar a dívida principal, vale apenas até o limite desta.", "Como garantia acessória, ela pode ser reduzida, mas não criar responsabilidade superior à obrigação garantida. O excesso é ajustado ao teto do débito principal.", "Dívida é de cinquenta mil, mas a fiança menciona sessenta mil; a garantia não supera cinquenta mil.", "O artigo reduz o excesso, não necessariamente invalida toda a fiança. Limites de valor, prazo e encargos devem ser examinados separadamente.", "Obrigação acessória", "obrigação cuja existência e alcance dependem de outra obrigação principal"),
    "824": row("Em regra, obrigação nula não pode ser garantida por fiança. A exceção é a nulidade causada apenas por incapacidade pessoal do devedor, salvo mútuo feito a menor.", "A garantia normalmente acompanha a validade da dívida. A lei preserva a fiança em hipótese restrita de incapacidade, mas retira dessa exceção o empréstimo concedido a menor.", "Contrato inválido por incapacidade pessoal pode manter a fiança, desde que não seja mútuo a menor.", "Outras causas de nulidade afastam a garantia. É preciso distinguir nulidade, anulabilidade e incapacidade, sem ampliar a exceção legal.", "Incapacidade pessoal", "limitação jurídica da pessoa para praticar validamente certos atos sem assistência ou representação"),
    "825": row("Quando alguém deve apresentar fiador, o credor pode recusar pessoa sem idoneidade, domicílio local ou patrimônio suficiente.", "O garantidor oferecido precisa demonstrar confiabilidade e capacidade econômica, além de estar domiciliado no município em que prestará a garantia. O credor não é obrigado a aceitar proteção inadequada.", "Devedor oferece fiador insolvente e residente longe do local exigido; o credor pode rejeitá-lo.", "A recusa deve apoiar-se nos critérios legais, não em preferência arbitrária. Suficiência patrimonial relaciona-se ao risco e ao valor da obrigação.", "Idoneidade", "aptidão e confiabilidade jurídica e econômica para assumir a garantia"),
    "826": row("Se o fiador perder capacidade ou se tornar insolvente, o credor pode exigir outro garantidor.", "A deterioração superveniente da garantia permite recompor a segurança originalmente esperada. O devedor deve apresentar substituto adequado quando o credor fizer a exigência cabível.", "Fiador sofre insolvência durante o contrato; o credor pede sua substituição por pessoa solvente.", "A substituição pressupõe insolvência ou incapacidade relevante, não simples queda de patrimônio. O novo fiador também deve preencher os requisitos legais.", "Insolvência", "situação em que o patrimônio não é suficiente para satisfazer as dívidas"),
}
